import { describe, expect, test } from 'vitest';
import { classifyUserMessage, humanText } from '../src/normalize/buddy-prompt.js';
import { inputText, reminder, wrapped } from './buddy-fixtures.js';

// Format reference 4.1 (what the human typed) and 4.2 (user messages that are not human).

const CAVEAT =
  '<system-reminder data-role="command-caveat">Caveat: The messages below were generated by the user while running local commands. DO NOT respond to these messages or otherwise consider them in your response unless the user explicitly asks you to.</system-reminder>';

describe('humanText (4.1)', () => {
  test('the user_query body of a wrapped part; the reminder around it goes', () => {
    expect(humanText([inputText(wrapped('fix the failing test'))])).toBe('fix the failing test');
  });

  test('every wrapper role in front of the query is stripped', () => {
    for (const role of ['user-context', 'current-context', 'additional-data', 'error-recovery', 'message-queue', 'command-caveat', 'compact-summary']) {
      expect(humanText([inputText(`${reminder(role)}\n<user_query>typed</user_query>`)])).toBe('typed');
    }
  });

  test('a bare (unwrapped) prompt is the text itself, trimmed; a plain string content too', () => {
    expect(humanText([inputText('  run the build  ')])).toBe('run the build');
    expect(humanText('run the build')).toBe('run the build');
  });

  test('parts are read one by one: a part that is only a reminder is dropped, the others joined by a line break', () => {
    expect(humanText([inputText(reminder('additional-data')), inputText('first'), inputText('second')])).toBe('first\nsecond');
  });

  test('several user_query bodies (in one part or several) are all kept, in order; text outside them is not', () => {
    expect(humanText([inputText('<user_query>one</user_query> and <user_query>two</user_query>')])).toBe('one\ntwo');
    expect(humanText([inputText(wrapped('one')), inputText('stray note'), inputText(wrapped('two'))])).toBe('one\ntwo');
  });

  test('reminders are stripped before the query is read (the engine: stripUserQueryXml(stripSystemReminderXml(t))): a query inside a reminder does not count', () => {
    expect(humanText([inputText('<system-reminder data-role="message-queue"><user_query>queued text</user_query></system-reminder>')])).toBeNull();
    expect(humanText([inputText('<system-reminder data-role="message-queue">queued: <user_query>OLD</user_query></system-reminder>\n<user_query>NEW</user_query>')])).toBe('NEW');
    expect(humanText([inputText('<system-reminder data-role="additional-data"><user_query>INJ</user_query></system-reminder>')])).toBeNull();
    // An attached file quoting a query, in front of the typed one.
    expect(humanText([inputText(`${reminder('additional-data', 'attached: <user_query>from the file</user_query>')}\n<user_query>typed</user_query>`)])).toBe('typed');
  });

  test('a literal, unclosed or unmatched tag in a bare prompt is plain text', () => {
    expect(humanText('what does <user_query> mean?')).toBe('what does <user_query> mean?');
    expect(humanText([inputText('close only </user_query> here')])).toBe('close only </user_query> here');
    expect(humanText([inputText('a <system-reminder> that never closes')])).toBe('a <system-reminder> that never closes');
    expect(humanText([inputText('see <image_local_path>/tmp/x.png and more')])).toBe('see <image_local_path>/tmp/x.png and more');
    // A complete pair elsewhere still decides: the literal part is then not a query part, the complete one is.
    expect(humanText([inputText('what does <user_query> mean?'), inputText(wrapped('the real ask'))])).toBe('the real ask');
  });

  test('the command caveat, a /clear command and local-command echoes or outputs are not human text', () => {
    expect(humanText([inputText(CAVEAT)])).toBeNull();
    expect(humanText([inputText('<command_name>/clear</command_name>')])).toBeNull();
    expect(humanText([inputText('<command-name>/model</command-name><command-args>glm</command-args>')])).toBeNull();
    expect(humanText([inputText('<command-message>compact</command-message>')])).toBeNull();
    expect(humanText([inputText('<bash-input>ls</bash-input>')])).toBeNull();
    expect(humanText([inputText('<user-memory-input>remember this</user-memory-input>')])).toBeNull();
    expect(humanText([inputText('<local-command-stdout>ok</local-command-stdout>')])).toBeNull();
    expect(humanText([inputText('<bash-stdout>a.ts</bash-stdout><bash-stderr></bash-stderr>')])).toBeNull();
  });

  test('envelopes of injected text are not human text', () => {
    for (const env of [
      '<cb_summary>summary</cb_summary>',
      '<conversation_history_summary><summary>s</summary></conversation_history_summary>',
      '<task-notification>done</task-notification>',
      '<monitor-event>tick</monitor-event>',
      '<teammate-message from="bob">hi</teammate-message>',
      '<turn_aborted>stopped</turn_aborted>',
    ]) {
      expect(humanText([inputText(env)])).toBeNull();
    }
  });

  test('image path markup is stripped; a channel envelope gives its content', () => {
    expect(humanText([inputText('look at this <image_local_path>/tmp/a.png</image_local_path>')])).toBe('look at this');
    expect(humanText([inputText('<channel source="lark" chat="c1">deploy now</channel>')])).toBe('deploy now');
  });

  test('images, files and blob refs are not text; nothing left is null', () => {
    expect(humanText([{ type: 'image_blob_ref', blob_id: 'b1', mime: 'image/png' }])).toBeNull();
    expect(humanText([{ type: 'input_image', image: 'data:image/png;base64,AAAA' }, inputText('what is this?')])).toBe('what is this?');
    expect(humanText([])).toBeNull();
    expect(humanText([inputText('   ')])).toBeNull();
    expect(humanText(undefined)).toBeNull();
    expect(humanText({ text: 'not an array' })).toBeNull();
  });
});

const user = (providerData: Record<string, unknown>, content: unknown = [inputText('hello')]): Record<string, unknown> => ({ type: 'message', role: 'user', content, providerData });

describe('classifyUserMessage (4.2): flags are read from providerData', () => {
  test('a plain user message is a prompt; queueHold is still a prompt', () => {
    expect(classifyUserMessage(user({ agent: 'cli' }))).toBe('prompt');
    expect(classifyUserMessage(user({ queueHold: true }))).toBe('prompt');
    expect(classifyUserMessage(user({ startsNewUserRequest: true }))).toBe('prompt');
    expect(classifyUserMessage({ type: 'message', role: 'user', content: [inputText('x')] })).toBe('prompt');
  });

  test('startsNewUserRequest false without isMeta: a queued real prompt', () => {
    expect(classifyUserMessage(user({ startsNewUserRequest: false }))).toBe('queued-prompt');
  });

  test('skipRun, isMeta (with or without startsNewUserRequest), isAdditionalData, isCompactInternal, agent compact (any case), teammate: hidden', () => {
    expect(classifyUserMessage(user({ skipRun: true }))).toBe('hidden');
    expect(classifyUserMessage(user({ isMeta: true }))).toBe('hidden');
    expect(classifyUserMessage(user({ isMeta: true, startsNewUserRequest: false }))).toBe('hidden');
    expect(classifyUserMessage(user({ isMeta: true, startsNewUserRequest: true }))).toBe('hidden');
    expect(classifyUserMessage(user({ isAdditionalData: true }))).toBe('hidden');
    expect(classifyUserMessage(user({ isCompactInternal: true }))).toBe('hidden');
    expect(classifyUserMessage(user({ agent: 'compact' }))).toBe('hidden');
    expect(classifyUserMessage(user({ agent: 'COMPACT' }))).toBe('hidden');
    expect(classifyUserMessage(user({ teammateMessage: { from: 'bob' } }))).toBe('hidden');
    expect(classifyUserMessage(user({}, [inputText('<teammate-message from="bob">hi</teammate-message>')]))).toBe('hidden');
  });

  test('the compaction boundary: isCompacted, isSummary, compactType, or summary content', () => {
    expect(classifyUserMessage(user({ isCompacted: true }))).toBe('compaction');
    expect(classifyUserMessage(user({ isSummary: true }))).toBe('compaction');
    expect(classifyUserMessage(user({ compactType: 'auto' }))).toBe('compaction');
    expect(classifyUserMessage(user({}, [inputText('<cb_summary>s</cb_summary>')]))).toBe('compaction');
    expect(classifyUserMessage(user({}, '<conversation_history_summary><summary>s</summary></conversation_history_summary>'))).toBe('compaction');
    expect(classifyUserMessage(user({}, [inputText('<system-reminder data-role="compact-summary">s</system-reminder>')]))).toBe('compaction');
    // The compact agent's own messages are not the boundary, whatever their content.
    expect(classifyUserMessage(user({ isCompactInternal: true }, [inputText('<cb_summary>s</cb_summary>')]))).toBe('hidden');
    expect(classifyUserMessage(user({ agent: 'compact', compactType: 'auto' }))).toBe('hidden');
  });

  test('flags at the top level of the record are not read (format reference D1)', () => {
    expect(classifyUserMessage({ ...user({}), isMeta: true, skipRun: true })).toBe('prompt');
  });

  test('anything that is not a user-role message is hidden', () => {
    expect(classifyUserMessage({ type: 'message', role: 'assistant', content: [] })).toBe('hidden');
    expect(classifyUserMessage({ type: 'reasoning', role: 'user' })).toBe('hidden');
    expect(classifyUserMessage(null)).toBe('hidden');
    expect(classifyUserMessage('x')).toBe('hidden');
  });
});
